// Recovery-code accounts: create / sign-in / step-up / replace flows, lockout (per identity, no global cap), revocation,
// inherit-only sign-in, weak-code policy, access integration, privacy.
// The code is generated by the browser (apps/web/lib/stdb/recoveryCode.ts); the module only stores sha256(pepper + code).
import { createHash } from 'node:crypto';
import { describe, expect, it } from 'vitest';
import { setup, mod, HEX, testCode } from './helpers';
import { sha256Hex } from '../src/sha256';
import { normalizeRecoveryCode, isRecoveryCodeShape, recoveryHash, RECOVERY_ALPHABET } from '../src/recovery_code';
import * as client from '../../apps/web/lib/stdb/recoveryCode';

const CODE = testCode('owner');
const CODE2 = testCode('other-owner');
const NEW_CODE = testCode('rotated');
const MIN = 60_000;
const HOUR_MS = 60 * MIN;
const BAD = testCode('wrong'); // valid shape, belongs to nobody

type S = ReturnType<typeof setup>;
const json = (x: unknown) => JSON.stringify(x, (_k, v) => (typeof v === 'bigint' ? v.toString() : v));

/** A reporter's assessed report with media, frame, steps, plus a verified owner of that property. */
function ownerWorld() {
  const s = setup();
  const reporter = s.user('reporter');
  const owner = s.user('owner');
  const rid = s.createReport(reporter);
  s.attach(reporter, rid, 'image', 3);
  s.call(reporter, mod.submit_report as any, { report_id: rid });
  const job = s.jobsFor(rid).find(j => j.state === 'queued')!;
  s.call(s.worker, mod.claim_job as any, { job_id: job.id, lease_ms: 60_000 });
  s.call(s.worker, mod.record_frame as any, { report_id: rid, frame_index: 0, t_sec: 1, thumb_key: `frames/${rid}/0.jpg`, finding_json: '{}' });
  s.call(s.worker, mod.record_agent_step as any, { report_id: rid, seq: 1, kind: 'tool_call', name: 'detail', summary: 'affected-only', visibility: 'affected' });
  s.call(s.worker, mod.record_assessment as any, { report_id: rid, json: '{"secret":"cost-detail"}', overall_level: 'major', usable_frames: 4, total_frames: 4, life_safety_csv: '' });
  s.call(s.worker, mod.complete_job as any, { job_id: job.id, ok: true });
  const v = s.verify(owner);
  s.call(owner, mod.save_affected_intake as any, { property_id: v.property_id, intake_json: '{"personaId":"p"}' });
  s.call(s.worker, mod.record_recovery_plan as any, { identity: s.idOf(owner).toHexString(), property_id: v.property_id, report_id: rid, json: '{"plan":"private"}' });
  const mediaKey = `media/${rid}/${HEX('3')}.jpg`;
  const read = (who: any) => (mod.read_blob as any)(s.h.procedureContext(who), { object_key: mediaKey, seq: 0 });
  const GATED = ['my_property_reports', 'my_report_privates', 'my_media_assets', 'my_frames', 'my_assessments', 'my_agent_steps', 'my_affected_profiles', 'my_recovery_plans'] as const;
  const counts = (who: any) => Object.fromEntries(GATED.map(n => [n, s.view(who, (mod as any)[n]).length]));
  return { s, reporter, owner, rid, propertyId: v.property_id, read, counts, GATED };
}


const makeAccount = (s: S, who: any, code = CODE) => {
  const r = s.createAccount(who, code);
  expect(r.ok, r.error).toBe(true);
};

describe('helpers', () => {
  it('sha256Hex matches node:crypto (empty, short, block boundaries, unicode)', () => {
    for (const m of ['', 'abc', 'a'.repeat(55), 'a'.repeat(56), 'a'.repeat(64), 'a'.repeat(1000), 'héllo wörld ✓ 😀']) {
      expect(sha256Hex(m)).toBe(createHash('sha256').update(m).digest('hex'));
    }
  });

  it('normalizes: uppercase, strips spaces/dashes, Crockford O->0 and I,L->1', () => {
    expect(normalizeRecoveryCode(' abcd-efgh jkmn-pqrs-tvwx ')).toBe('ABCDEFGHJKMNPQRSTVWX');
    expect(normalizeRecoveryCode('oOiIlL')).toBe('001111');
    expect(normalizeRecoveryCode('a\u2013b\tc\nd')).toBe('ABCD');
    expect(normalizeRecoveryCode(undefined as any)).toBe('');
  });

  it('shape: exactly 20 alphabet chars that pass the weak-code policy', () => {
    const good = 'A7C2E9G4K1M8P3R6T5W0'; // 20 distinct, no sequences
    expect(isRecoveryCodeShape(good)).toBe(true);
    expect(isRecoveryCodeShape('a7c2-e9g4-k1m8-p3r6-t5w0')).toBe(true);
    expect(isRecoveryCodeShape('OILO-ILOI-LOIL-OILO-ILOI')).toBe(false); // folds to 0/1 only
    expect(isRecoveryCodeShape('A'.repeat(20))).toBe(false); // 1 distinct
    expect(isRecoveryCodeShape('A7C2E9G4K' + 'A'.repeat(11))).toBe(false); // 9 distinct (and a run of 11)
    expect(isRecoveryCodeShape(good + '2')).toBe(false); // 21
    expect(isRecoveryCodeShape(good.slice(1))).toBe(false); // 19
    expect(isRecoveryCodeShape('A7C2E9G4K1M8P3R6T5WU')).toBe(false); // U is not in the alphabet
    expect(isRecoveryCodeShape('')).toBe(false);
    expect(isRecoveryCodeShape(undefined as any)).toBe(false);
    for (let i = 0; i < 20; i++) expect(isRecoveryCodeShape(testCode(i))).toBe(true);
  });

  it('weak-code policy: 10+ distinct, no 6+ alphabet-consecutive run, no period <= 8, no run of 4 identical', () => {
    // the three named examples
    for (const weak of ['0123456789ABCDEFGHJK', 'ABCDEFGHABCDEFGHABCD', '01234567890123456789']) {
      expect(isRecoveryCodeShape(weak), weak).toBe(false);
      expect(client.isRecoveryCodeShape(weak), weak).toBe(false);
    }
    const ok = 'A7C2E9G4K1M8P3R6T5W0';
    expect(isRecoveryCodeShape(ok)).toBe(true);
    // distinct characters: 9 fails, 10 passes (no runs, sequences or periods involved)
    expect(isRecoveryCodeShape('A7C2E9G4K' + 'K4G9E2C7A' + 'A7')).toBe(false); // 9 distinct
    expect(isRecoveryCodeShape('A7C2E9G4KM' + 'M4G9E2C7AK')).toBe(true); // 10 distinct
    // alphabet-consecutive runs (the alphabet skips I, L, O, U): 6 is rejected ascending and descending, 5 is fine
    expect(isRecoveryCodeShape('ABCDEF' + '7K2M9P4R1T8W0X')).toBe(false); // ascending 6
    expect(isRecoveryCodeShape('ABCDE' + '7K2M9P4R1T8W0XZ')).toBe(true); // ascending 5
    expect(isRecoveryCodeShape('7K2M9P4R1T8W0X' + 'FEDCBA')).toBe(false); // descending 6
    expect(isRecoveryCodeShape('7K2M9P4R1T8W0X' + 'FEDCB' + 'Z')).toBe(true); // descending 5
    expect(isRecoveryCodeShape('7K2M9' + 'GHJKMN' + 'P4R1T8W03')).toBe(false); // G H J K M N are consecutive in the alphabet
    // repeating periods: <= 8 is rejected (with 10+ distinct required this is defense in depth), 10 is allowed
    expect(isRecoveryCodeShape('A7C2E9G4' + 'A7C2E9G4' + 'A7C2')).toBe(false); // period 8
    expect(isRecoveryCodeShape('A7C2E9G4K1' + 'A7C2E9G4K1')).toBe(true); // period 10, 10 distinct
    expect(isRecoveryCodeShape('A7C2E9G4K1' + 'A7C2E9G4K2')).toBe(true); // nearly periodic is fine
    // runs of identical characters: 4 is rejected, 3 is fine
    expect(isRecoveryCodeShape('A7C2E9G4' + 'KKKK' + '1M8P3R6T')).toBe(false);
    expect(isRecoveryCodeShape('A7C2E9G4' + 'KKK' + '1M8P3R6T5')).toBe(true);
  });

  it('over-long input is rejected before normalizing (free invalid_code)', () => {
    const ok = 'A7C2E9G4K1M8P3R6T5W0';
    expect(isRecoveryCodeShape(ok + ' '.repeat(44))).toBe(true); // exactly 64 chars still fine
    expect(isRecoveryCodeShape(ok + ' '.repeat(45))).toBe(false); // 65
    expect(isRecoveryCodeShape(ok + '-'.repeat(1_000_000))).toBe(false);
    expect(client.isRecoveryCodeShape(ok + ' '.repeat(45))).toBe(false);
  });

  it('the client generator never returns a code the policy rejects, even from adversarial random sources', () => {
    // a source that first yields all zero bytes (-> 'AAAA...'-like runs) then a counting pattern, then real randomness
    let calls = 0;
    const g = client.generateRecoveryCode(buf => {
      calls++;
      if (calls <= 2) buf.fill(0);
      else if (calls <= 4) for (let i = 0; i < buf.length; i++) buf[i] = i; // counting: sequential characters
      else for (let i = 0; i < buf.length; i++) buf[i] = (i * 7 + calls * 13) % 224;
    });
    expect(isRecoveryCodeShape(g)).toBe(true);
    expect(calls).toBeGreaterThan(4);
    for (let i = 0; i < 200; i++) expect(isRecoveryCodeShape(client.generateRecoveryCode())).toBe(true);
  });

  it('module and browser helpers agree on a fixed corpus', () => {
    const corpus = [
      '', ' ', 'abc', CODE, CODE.toLowerCase(), CODE.replace(/-/g, ' '), 'OILO-ILOI-LOIL-OILO-ILOI', 'A'.repeat(20), 'ABCDEFGH'.repeat(3),
      'abcd-efgh-2345-6789-jkmn', 'abcd\u2010efgh\u2014 2345\t6789\njkmn', 'ABCDEFGH23456789JKMU', '0123456789ABCDEFGHJK', 'ABCDEFGHABCDEFGHABCD', '01234567890123456789', 'A7C2E9G4K1M8P3R6T5W0', 'A7C2E9G4KKKK1M8P3R6T', 'A7C2E9G4K1M8P3R6T5W0' + ' '.repeat(60), 'ÀBCD-EFGH-2345-6789-JKMN', 'ß'.repeat(10),
      'ABCDEFG' + 'A'.repeat(13), 'ABCDEFGH' + 'A'.repeat(12), ' a-b c ', '😀'.repeat(5), 'lIoO1l0', 'zzzz-zzzz-zzzz-zzzz-zzzz',
      ...Array.from({ length: 30 }, (_, i) => testCode(`corpus-${i}`)),
      ...Array.from({ length: 30 }, (_, i) => testCode(`corpus-${i}`).toLowerCase().replace(/-/g, ' ').replace(/0/g, 'o').replace(/1/g, 'l')),
    ];
    for (const c of corpus) {
      expect(client.normalizeRecoveryCode(c), JSON.stringify(c)).toBe(normalizeRecoveryCode(c));
      expect(client.isRecoveryCodeShape(c), JSON.stringify(c)).toBe(isRecoveryCodeShape(c));
    }
    // a freshly generated browser code is always accepted by the module
    for (let i = 0; i < 50; i++) {
      const g = client.generateRecoveryCode();
      expect(g).toMatch(/^[0-9A-Z]{4}(-[0-9A-Z]{4}){4}$/);
      expect(isRecoveryCodeShape(g)).toBe(true);
      for (const ch of g.replace(/-/g, '')) expect(RECOVERY_ALPHABET).toContain(ch);
    }
  });
});

describe('config and status', () => {
  it('my_account_status is enabled by default and follows admin_set_account_config', () => {
    const s = setup();
    const owner = s.user('owner');
    expect(s.view(owner, mod.my_account_status as any)).toEqual([{ id: 0, enabled: true }]);
    s.configureAccounts({ accounts_enabled: false });
    expect(s.view(owner, mod.my_account_status as any)).toEqual([{ id: 0, enabled: false }]);
    s.configureAccounts({ accounts_enabled: true });
    expect(s.view(owner, mod.my_account_status as any)).toEqual([{ id: 0, enabled: true }]);
  });

  it('admin_set_account_config is admin-only, keeps omitted values and the pepper, never leaks the pepper', () => {
    const s = setup();
    const alice = s.user('alice');
    expect(() => s.call(alice, mod.admin_set_account_config as any, { accounts_enabled: false, require_stepup: undefined })).toThrow(/admin only/);
    expect(s.view(s.internal, mod.admin_account_config as any)).toEqual([{ id: 0, accounts_enabled: true, require_stepup: false, has_pepper: false }]); // defaults, no row yet
    expect(s.view(alice, mod.admin_account_config as any)).toEqual([]);
    s.configureAccounts({ require_stepup: true });
    const pepper = s.h.db.account_config.id.find(0)!.hash_pepper;
    expect(pepper).toMatch(/^[0-9a-f]{64}$/);
    s.configureAccounts({ accounts_enabled: false });
    const cfg = s.h.db.account_config.id.find(0)!;
    expect(cfg).toMatchObject({ accounts_enabled: false, require_stepup: true, hash_pepper: pepper }); // omitted args keep, pepper never rotated
    expect(s.view(s.internal, mod.admin_account_config as any)).toEqual([
      { id: 0, accounts_enabled: false, require_stepup: true, has_pepper: true },
    ]);
    expect(s.view(alice, mod.admin_account_config as any)).toEqual([]);
    for (const who of [alice, s.internal]) {
      for (const name of Object.keys(mod).filter(n => n.startsWith('my_') || n.startsWith('admin_account'))) {
        expect(json(s.view(who, (mod as any)[name])), name).not.toContain(pepper);
      }
    }
  });

  it('the pepper is generated lazily by the first create/sign-in when no admin ever configured anything', () => {
    const { s, owner } = ownerWorld();
    expect(s.h.db.account_config.count()).toBe(0n);
    makeAccount(s, owner);
    const cfg = s.h.db.account_config.id.find(0)!;
    expect(cfg).toMatchObject({ accounts_enabled: true, require_stepup: false });
    expect(cfg.hash_pepper).toMatch(/^[0-9a-f]{64}$/);
    s.configureAccounts({ require_stepup: false });
    expect(s.h.db.account_config.id.find(0)!.hash_pepper).toBe(cfg.hash_pepper);
  });

  it('accounts_enabled=false rejects create and sign-in, but existing devices keep working', () => {
    const { s, owner, counts } = ownerWorld();
    makeAccount(s, owner);
    s.configureAccounts({ accounts_enabled: false });
    const d2 = s.user('d2');
    expect(s.signIn(d2, CODE)).toMatchObject({ ok: false, error: 'accounts_disabled' });
    const o2 = s.user('o2');
    s.verify(o2, { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' });
    expect(s.createAccount(o2, CODE2)).toMatchObject({ ok: false, error: 'accounts_disabled' });
    expect(s.h.db.account.count()).toBe(1n);
    expect(s.h.db.code_attempt.count()).toBe(0n); // refusals are not failed attempts
    expect(s.view(owner, mod.my_devices as any)).toHaveLength(1);
    expect(counts(owner).my_property_reports).toBe(1);
    expect(s.stepUp(owner, CODE).ok).toBe(true);
    s.configureAccounts({ accounts_enabled: true });
    expect(s.signIn(d2, CODE).ok).toBe(true);
  });
});

describe('create_account', () => {
  it('a verified owner creates an account; only the hash is kept; device linked, property bound, audit logged', () => {
    const { s, owner, propertyId } = ownerWorld();
    const r = s.createAccount(owner, CODE);
    expect(r).toEqual({ ok: true, error: '', retry_after_s: 0, attempts_left: 5 });
    const rows = [...s.h.db.account.iter()];
    expect(rows).toHaveLength(1);
    const pepper = s.h.db.account_config.id.find(0)!.hash_pepper;
    expect(rows[0]!.recovery_hash).toBe(recoveryHash(pepper, normalizeRecoveryCode(CODE)));
    expect(rows[0]!.recovery_hash).toMatch(/^[0-9a-f]{64}$/);
    expect(rows[0]!.replaced_at).toBeUndefined();
    // typed form is irrelevant: the lowercase / spaced / lookalike form of the same code hashes identically
    expect(normalizeRecoveryCode(CODE.toLowerCase().replace(/-/g, ' '))).toBe(normalizeRecoveryCode(CODE));
    const acct = s.view(owner, mod.my_account as any);
    expect(acct).toHaveLength(1);
    expect(Object.keys(acct[0]).sort()).toEqual(['created_at', 'id', 'last_login_at']);
    const devs = s.view(owner, mod.my_devices as any);
    expect(devs).toHaveLength(1);
    expect(devs[0]).toMatchObject({ is_current: true, identity_hex: s.idOf(owner).toHexString() });
    expect(s.view(owner, mod.my_stepup as any)[0]).toMatchObject({ linked: true, active: true, require_stepup: false });
    expect([...s.h.db.account_property.iter()].map(b => b.property_id)).toEqual([propertyId]);
    expect([...s.h.db.access_log.iter()].filter(a => a.kind === 'claim' && a.property_id === propertyId)).toHaveLength(1);
    // step-up window is 15 minutes
    const dev = s.h.db.account_device.identity.find(s.idOf(owner))!;
    expect(Number(dev.stepup_until!.microsSinceUnixEpoch - s.clock.now().microsSinceUnixEpoch)).toBe(15 * MIN * 1000);
    // nothing at rest holds the plaintext code
    const all = json([s.h.db.account.iter(), s.h.db.account_device.iter(), s.h.db.account_config.iter(), s.h.db.code_attempt.iter()].map(i => [...i]));
    expect(all).not.toContain(normalizeRecoveryCode(CODE));
    expect(all).not.toContain(CODE);
  });

  it('only verified owners, and only once: stranger, reporter, pending verification and signed-in devices are refused', () => {
    const { s, reporter, owner } = ownerWorld();
    expect(s.createAccount(s.user('stranger'), CODE2)).toMatchObject({ ok: false, error: 'not_verified_owner' });
    expect(s.createAccount(reporter, CODE2)).toMatchObject({ ok: false, error: 'not_verified_owner' });
    const pending = s.user('pending');
    s.call(pending, mod.start_verification as any, {
      address_json: JSON.stringify({ line1: '5 Pending Way', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.8, lng: -96.8, normalized: 'x', source: 'census' }),
      doc_kind: 'drivers_license',
      secret_hash: HEX('b'),
    });
    expect(s.createAccount(pending, CODE2)).toMatchObject({ ok: false, error: 'not_verified_owner' });
    expect(s.h.db.account.count()).toBe(0n);
    makeAccount(s, owner);
    expect(s.createAccount(owner, NEW_CODE)).toMatchObject({ ok: false, error: 'already_signed_in' });
    expect(s.h.db.account.count()).toBe(1n);
  });

  it('rejects weak or malformed codes with invalid_code and spends no attempt', () => {
    const { s, owner } = ownerWorld();
    const weak = ['', 'short', 'A'.repeat(20), 'ABCDEFG' + 'A'.repeat(13), 'OILO-ILOI-LOIL-OILO-ILOI', 'ABCDEFGH23456789JKMU', CODE + 'A', 'ABCDEFGH23456789JK!M'];
    for (const w of weak) expect(s.createAccount(owner, w), JSON.stringify(w)).toMatchObject({ ok: false, error: 'invalid_code' });
    expect(s.h.db.account.count()).toBe(0n);
    expect(s.h.db.code_attempt.count()).toBe(0n);
    makeAccount(s, owner);
  });

  it('a duplicate hash is code_taken, and counts as a failed attempt (it would otherwise be a probe of other codes)', () => {
    const w = ownerWorld();
    makeAccount(w.s, w.owner, CODE);
    const o2 = w.s.user('o2');
    w.s.verify(o2, { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' });
    const r = w.s.createAccount(o2, CODE.toLowerCase().replace(/-/g, ' '));
    expect(r).toMatchObject({ ok: false, error: 'code_taken', attempts_left: 4 });
    expect(w.s.h.db.account.count()).toBe(1n);
    expect(w.s.h.db.code_attempt.count()).toBe(1n);
    expect(w.s.createAccount(o2, CODE2).ok).toBe(true);
    expect(w.s.h.db.code_attempt.count()).toBe(1n); // a success does NOT clear failures (they age out of the 15 min window)
  });
});

describe('sign_in_with_code', () => {
  it('grants the account properties on a second device; sign_out removes the inheritance', () => {
    const { s, owner, propertyId, read, counts } = ownerWorld();
    makeAccount(s, owner);
    const d2 = s.user('new-device');
    expect(counts(d2).my_property_reports).toBe(0);
    expect(read(d2).error).toBe('forbidden');

    // typed sloppily: lowercase, spaces, lookalike letters all normalize to the same code
    const res = s.signIn(d2, CODE.toLowerCase().replace(/-/g, ' '));
    expect(res).toEqual({ ok: true, error: '', retry_after_s: 0, attempts_left: 5 });
    expect(s.view(d2, mod.my_account as any)).toHaveLength(1);
    expect(s.view(d2, mod.my_devices as any)).toHaveLength(2);
    expect(s.view(owner, mod.my_devices as any)).toHaveLength(2);
    expect(s.view(d2, mod.my_devices as any).filter((d: any) => d.is_current)).toHaveLength(1);
    expect(s.view(d2, mod.my_stepup as any)[0]).toMatchObject({ linked: true, active: true });

    const c = counts(d2);
    expect(c.my_property_reports).toBe(1);
    expect(c.my_assessments).toBe(1);
    expect(c.my_media_assets).toBe(1);
    expect(c.my_frames).toBe(1);
    expect(s.view(d2, mod.my_agent_steps as any).map((x: any) => x.visibility)).toEqual(['affected']);
    expect(c.my_affected_profiles).toBe(1);
    expect(c.my_recovery_plans).toBe(1);
    expect(s.view(d2, mod.my_verifications as any).some((v: any) => v.property_id === propertyId && v.state === 'verified')).toBe(true);
    expect(s.view(d2, mod.my_property_privates as any)).toHaveLength(1);
    expect(read(d2).ok).toBe(true);
    s.call(d2, mod.save_affected_intake as any, { property_id: propertyId, intake_json: '{"personaId":"q"}' });
    const acct = s.h.db.account.iter().next().value!;
    expect(acct.last_login_at.microsSinceUnixEpoch).toBeGreaterThanOrEqual(acct.created_at.microsSinceUnixEpoch);

    s.call(d2, mod.sign_out_device as any, {});
    expect(counts(d2).my_property_reports).toBe(0);
    expect(read(d2).error).toBe('forbidden');
    expect(s.view(d2, mod.my_devices as any)).toHaveLength(0);
    expect(s.view(owner, mod.my_devices as any)).toHaveLength(1);
    expect(() => s.call(d2, mod.sign_out_device as any, {})).toThrow(/not_signed_in/);
  });

  it('updates last_login_at', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    const t0 = s.view(owner, mod.my_account as any)[0].last_login_at.microsSinceUnixEpoch;
    s.advanceMs(5 * MIN);
    expect(s.signIn(s.user('d2'), CODE).ok).toBe(true);
    const t1 = s.view(owner, mod.my_account as any)[0].last_login_at.microsSinceUnixEpoch;
    expect(t1 - t0).toBe(5n * 60n * 1_000_000n);
  });

  it('properties belong to the account: signing out of the verifying device does not orphan them', () => {
    const { s, owner, counts, read, propertyId } = ownerWorld();
    makeAccount(s, owner);
    expect(s.h.db.account_property.count()).toBe(1n);
    s.call(owner, mod.sign_out_device as any, {});
    const d2 = s.user('d2');
    s.signIn(d2, CODE);
    expect(counts(d2).my_property_reports).toBe(1);
    expect(read(d2).ok).toBe(true);
    expect(s.view(d2, mod.my_verifications as any).some((v: any) => v.property_id === propertyId && v.state === 'verified')).toBe(true);
    // CHANGED (finding 4): sign_out_device revokes the device, so it no longer keeps even what it verified itself
    // (until it signs in again or completes a new verification).
    expect(counts(owner).my_property_reports).toBe(0);
    expect(s.signIn(owner, CODE).ok).toBe(true);
    expect(counts(owner).my_property_reports).toBe(1);
  });

  it('a verification completed AFTER signing in binds to the account; sign-in is inherit-only for a device that verified before', () => {
    const { s, owner, propertyId } = ownerWorld();
    makeAccount(s, owner);
    const d2 = s.user('d2');
    const other = { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' };
    const v2 = s.verify(d2, other);
    s.signIn(d2, CODE);
    // CHANGED (finding 3): signing in no longer pushes d2's own verified property into the account
    expect(s.h.db.account_property.count()).toBe(1n);
    expect([...s.h.db.account_property.iter()].some(b => b.property_id === v2.property_id)).toBe(false);
    expect(s.view(owner, mod.my_property_privates as any).map((p: any) => p.property_id)).toEqual([propertyId]);
    const d3 = s.user('d3');
    s.signIn(d3, CODE);
    const v3 = s.verify(d3, { ...other, line1: '1 New Place', lat: 33.1 }); // d3 IS linked when it completes: this one binds
    expect([...s.h.db.account_property.iter()].some(b => b.property_id === v3.property_id)).toBe(true);
    expect(s.view(owner, mod.my_verifications as any).some((v: any) => v.property_id === v3.property_id)).toBe(true);
  });

  it('a device already signed in to another account gets already_signed_in; the same account is a harmless refresh', () => {
    const w = ownerWorld();
    makeAccount(w.s, w.owner, CODE);
    const o2 = w.s.user('o2');
    w.s.verify(o2, { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' });
    makeAccount(w.s, o2, CODE2);
    expect(w.s.signIn(o2, CODE)).toMatchObject({ ok: false, error: 'already_signed_in' });
    expect(w.s.signIn(o2, CODE2).ok).toBe(true);
    expect(w.s.view(o2, mod.my_devices as any)).toHaveLength(1);
  });

  it('every failure is the SAME invalid_code: wrong code, near-miss, unknown, malformed, right account wrong digit', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    const nearMiss = CODE.slice(0, -1) + (CODE.endsWith('7') ? '8' : '7');
    const results = [BAD, nearMiss, 'AAAA-AAAA-AAAA-AAAA-AAAA', 'nonsense', ''].map(c => {
      const d = s.user(`probe-${c}`);
      return s.signIn(d, c);
    });
    for (const r of results) expect(r).toMatchObject({ ok: false, error: 'invalid_code', retry_after_s: 0 });
    // identical shape for a near-miss and a code that matches nothing at all (attempts_left aside)
    expect(results[0]).toEqual(results[1]);
    // none of them linked anything
    expect(s.h.db.account_device.count()).toBe(1n);
  });

  it('locks an identity after 5 failures for 15 minutes; the correct code does not unlock early; counts only failures', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    const d = s.user('attacker');
    for (let i = 1; i <= 4; i++) expect(s.signIn(d, testCode(`g${i}`))).toMatchObject({ ok: false, error: 'invalid_code', attempts_left: 5 - i });
    // 5th failure locks right away
    const fifth = s.signIn(d, testCode('g5'));
    expect(fifth).toMatchObject({ ok: false, error: 'locked', attempts_left: 0 });
    expect(fifth.retry_after_s).toBeGreaterThan(14 * 60);
    expect(fifth.retry_after_s).toBeLessThanOrEqual(15 * 60);
    expect(s.h.db.code_attempt.count()).toBe(5n);
    // locked: even the right code is refused, and attempts are no longer recorded
    s.advanceMs(10 * MIN);
    const still = s.signIn(d, CODE);
    expect(still).toMatchObject({ ok: false, error: 'locked' });
    expect(still.retry_after_s).toBeGreaterThan(4 * 60);
    expect(still.retry_after_s).toBeLessThanOrEqual(5 * 60);
    expect(s.h.db.code_attempt.count()).toBe(5n);
    expect(s.view(d, mod.my_account as any)).toHaveLength(0);
    // other identities are unaffected
    expect(s.signIn(s.user('friend'), CODE).ok).toBe(true);
    // 15 minutes after the failures the lock is gone
    s.advanceMs(5 * MIN + 1000);
    expect(s.signIn(d, CODE).ok).toBe(true);
    expect(s.h.db.code_attempt.count()).toBe(5n); // CHANGED (finding 2): a success keeps the rows; they age out
  });

  it('a success does NOT wipe the identity\'s failures: alternating 4 wrong guesses with a valid call still locks (finding 2)', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    const d = s.user('alternator');
    for (let i = 0; i < 4; i++) s.signIn(d, testCode(`x${i}`));
    expect(s.h.db.code_attempt.count()).toBe(4n);
    expect(s.signIn(d, CODE).ok).toBe(true); // d is now linked; its failures stay
    expect(s.h.db.code_attempt.count()).toBe(4n);
    // a step-up (same account, valid) also keeps them
    expect(s.stepUp(d, CODE).ok).toBe(true);
    expect(s.h.db.code_attempt.count()).toBe(4n);
    expect(s.stepUp(d, testCode('x-next'))).toMatchObject({ ok: false, error: 'locked' }); // the 5th failure locks
    s.advanceMs(15 * MIN + 1000);
    expect(s.stepUp(d, CODE).ok).toBe(true);
  });

  it('there is NO global failure cap: many identities failing never makes anyone (right code included) rate_limited (finding 1)', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    for (let i = 0; i < 320; i++) {
      const who = s.user(`bot-${Math.floor(i / 4)}`); // 4 failures per identity: never locked individually
      expect(s.signIn(who, testCode(`bot${i}`)).error).toBe('invalid_code');
    }
    expect(s.h.db.code_attempt.count()).toBe(320n);
    const late = s.user('late');
    expect(s.signIn(late, CODE)).toMatchObject({ ok: true, error: '' });
    expect(s.stepUp(owner, CODE).ok).toBe(true);
    const c = s.user('c');
    s.verify(c, { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' });
    expect(s.createAccount(c, CODE2).ok).toBe(true);
    // no code path can ever answer 'rate_limited' any more
    expect(s.signIn(s.user('wrong'), BAD).error).toBe('invalid_code');
  });

  it('over-long codes are a free invalid_code (nothing recorded)', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    const d = s.user('long');
    for (let i = 0; i < 10; i++) expect(s.signIn(d, CODE + ' '.repeat(100))).toMatchObject({ ok: false, error: 'invalid_code', attempts_left: 5 });
    expect(s.h.db.code_attempt.count()).toBe(0n);
    expect(s.signIn(d, CODE).ok).toBe(true);
  });

  it('the 60 s tick purges ledger rows older than 24 hours', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    s.signIn(s.user('d'), BAD);
    s.advanceMs(23 * HOUR_MS);
    s.tick();
    expect(s.h.db.code_attempt.count()).toBe(1n);
    s.advanceMs(HOUR_MS + 1000);
    s.tick();
    expect(s.h.db.code_attempt.count()).toBe(0n);
  });
});

describe('step-up gating (account_config.require_stepup)', () => {
  it('off by default: owners without an account keep full access', () => {
    const { s, owner, counts, read } = ownerWorld();
    expect(s.view(owner, mod.my_stepup as any)[0]).toMatchObject({ linked: false, active: false, require_stepup: false });
    for (const v of Object.values(counts(owner))) expect(v).toBeGreaterThan(0);
    expect(read(owner).ok).toBe(true);
  });

  it('on: no account = no full report; creating or stepping up restores it; expiry removes it after the tick', () => {
    const { s, owner, counts, read, GATED } = ownerWorld();
    s.configureAccounts({ require_stepup: true });
    expect(s.view(owner, mod.my_stepup as any)[0]).toMatchObject({ require_stepup: true, linked: false });
    for (const n of GATED) expect(counts(owner)[n], n).toBe(0);
    expect(read(owner).error).toBe('stepup_required');
    expect(s.view(owner, mod.my_verifications as any)).toHaveLength(1);
    expect(s.view(owner, mod.my_property_privates as any)).toHaveLength(1);

    makeAccount(s, owner);
    for (const n of GATED) expect(counts(owner)[n], n).toBeGreaterThan(0);
    expect(read(owner).ok).toBe(true);

    // 16 minutes later with no tick: views can't see the clock, but read_blob (a procedure) can.
    s.advanceMs(16 * MIN);
    expect(read(owner).error).toBe('stepup_required');
    expect(counts(owner).my_property_reports).toBe(1);
    s.tick();
    for (const n of GATED) expect(counts(owner)[n], n).toBe(0);
    expect(s.view(owner, mod.my_stepup as any)[0]).toMatchObject({ linked: true, active: false });

    // Wrong code: still locked out, identical invalid_code.
    expect(s.stepUp(owner, BAD)).toMatchObject({ ok: false, error: 'invalid_code', attempts_left: 4 });
    expect(read(owner).error).toBe('stepup_required');
    // Right code: restored for 15 minutes.
    expect(s.stepUp(owner, CODE)).toMatchObject({ ok: true, error: '' });
    for (const n of GATED) expect(counts(owner)[n], n).toBeGreaterThan(0);
    expect(read(owner).ok).toBe(true);
    s.advanceMs(14 * MIN);
    expect(read(owner).ok).toBe(true);
    s.advanceMs(2 * MIN);
    expect(read(owner).error).toBe('stepup_required');
    s.tick();
    expect(counts(owner).my_property_reports).toBe(0);
  });

  it('step-up needs a signed-in device and THE CALLER\'S OWN account code', () => {
    const w = ownerWorld();
    expect(w.s.stepUp(w.owner, CODE)).toMatchObject({ ok: false, error: 'not_signed_in' });
    makeAccount(w.s, w.owner, CODE);
    const o2 = w.s.user('o2');
    w.s.verify(o2, { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' });
    makeAccount(w.s, o2, CODE2);
    // o2 knows an account code, but not its own: the other account's code is just a wrong code
    expect(w.s.stepUp(o2, CODE)).toMatchObject({ ok: false, error: 'invalid_code' });
    expect(w.s.stepUp(o2, CODE2).ok).toBe(true);
  });

  it('step-up wrong codes lock the identity like sign-in does', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    for (let i = 1; i <= 4; i++) expect(s.stepUp(owner, testCode(`s${i}`)).error).toBe('invalid_code');
    expect(s.stepUp(owner, testCode('s5'))).toMatchObject({ ok: false, error: 'locked' });
    expect(s.stepUp(owner, CODE)).toMatchObject({ ok: false, error: 'locked' });
    s.advanceMs(15 * MIN + 1000);
    expect(s.stepUp(owner, CODE).ok).toBe(true);
  });

  it('on: a device that signs in gets a step-up window and the account properties', () => {
    const { s, owner, counts } = ownerWorld();
    makeAccount(s, owner);
    s.configureAccounts({ require_stepup: true });
    const d2 = s.user('d2');
    expect(counts(d2).my_property_reports).toBe(0);
    s.signIn(d2, CODE);
    expect(counts(d2).my_property_reports).toBe(1);
    s.advanceMs(16 * MIN);
    s.tick();
    expect(counts(d2).my_property_reports).toBe(0);
    expect(s.view(d2, mod.my_devices as any)).toHaveLength(2); // still signed in, just no step-up
  });

  it('toggling require_stepup re-evaluates immediately (config row change)', () => {
    const { s, owner, counts } = ownerWorld();
    s.configureAccounts({ require_stepup: true });
    expect(counts(owner).my_property_reports).toBe(0);
    s.configureAccounts({ require_stepup: false });
    expect(counts(owner).my_property_reports).toBe(1);
  });
});

describe('replace_recovery_code', () => {
  it('the old code stops working, the new one works, other devices stay linked', () => {
    const { s, owner, counts } = ownerWorld();
    makeAccount(s, owner);
    const d2 = s.user('d2');
    expect(s.signIn(d2, CODE).ok).toBe(true);
    const before = [...s.h.db.account.iter()][0]!;
    s.advanceMs(MIN);
    expect(s.replaceCode(owner, CODE, NEW_CODE)).toEqual({ ok: true, error: '', retry_after_s: 0, attempts_left: 5 });
    const after = [...s.h.db.account.iter()][0]!;
    expect(after.id).toBe(before.id);
    expect(after.recovery_hash).not.toBe(before.recovery_hash);
    expect(after.replaced_at).toBeDefined();
    expect(s.view(owner, mod.my_devices as any)).toHaveLength(2); // d2 stays linked
    expect(counts(d2).my_property_reports).toBe(1);
    const d3 = s.user('d3');
    expect(s.signIn(d3, CODE)).toMatchObject({ ok: false, error: 'invalid_code' });
    expect(s.signIn(d3, NEW_CODE).ok).toBe(true);
    expect(s.stepUp(owner, CODE).ok).toBe(false);
    expect(s.stepUp(owner, NEW_CODE).ok).toBe(true);
    expect(s.h.db.account.count()).toBe(1n);
    expect(s.h.db.account_property.count()).toBe(1n);
  });

  it('needs a signed-in device, the right old code (same failure limits), a valid new code that is different and unused', () => {
    const w = ownerWorld();
    expect(w.s.replaceCode(w.owner, CODE, NEW_CODE)).toMatchObject({ ok: false, error: 'not_signed_in' });
    makeAccount(w.s, w.owner);
    expect(w.s.replaceCode(w.owner, BAD, NEW_CODE)).toMatchObject({ ok: false, error: 'invalid_code', attempts_left: 4 });
    expect(w.s.replaceCode(w.owner, CODE, 'weak')).toMatchObject({ ok: false, error: 'invalid_new_code' });
    expect(w.s.replaceCode(w.owner, CODE, 'A'.repeat(20))).toMatchObject({ ok: false, error: 'invalid_new_code' });
    expect(w.s.replaceCode(w.owner, CODE, CODE.toLowerCase())).toMatchObject({ ok: false, error: 'code_unchanged' });
    const o2 = w.s.user('o2');
    w.s.verify(o2, { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' });
    makeAccount(w.s, o2, CODE2);
    // CHANGED (finding 6): a taken new code is the generic 'invalid_new_code' AND costs a failure (no free oracle for live codes)
    const attemptsBefore = w.s.h.db.code_attempt.count();
    expect(w.s.replaceCode(w.owner, CODE, CODE2)).toMatchObject({ ok: false, error: 'invalid_new_code', attempts_left: 3 });
    expect(w.s.h.db.code_attempt.count()).toBe(attemptsBefore + 1n);
    expect(w.s.replaceCode(w.owner, CODE, 'weak')).toEqual({ ok: false, error: 'invalid_new_code', retry_after_s: 0, attempts_left: 0 }); // malformed: free, same code
    expect(w.s.h.db.code_attempt.count()).toBe(attemptsBefore + 1n);
    expect(w.s.signIn(w.s.user('x'), CODE).ok).toBe(true); // nothing changed
    w.s.replaceCode(w.owner, CODE, CODE2); // 3 failures so far (BAD, CODE2) -> this is the 3rd
    expect(w.s.replaceCode(w.owner, BAD, NEW_CODE)).toMatchObject({ ok: false, error: 'invalid_code', attempts_left: 1 });
    expect(w.s.replaceCode(w.owner, BAD, NEW_CODE)).toMatchObject({ ok: false, error: 'locked' });
    expect(w.s.replaceCode(w.owner, CODE, NEW_CODE)).toMatchObject({ ok: false, error: 'locked' });
  });
});

const FAR = { line1: '900 Far Road', city: 'Dallas', state: 'TX', zip: '75201', lat: 32.9, lng: -96.797, normalized: 'x', source: 'census' };

describe('devices and account deletion', () => {
  function twoDevices() {
    const w = ownerWorld();
    makeAccount(w.s, w.owner);
    const d2 = w.s.user('d2');
    w.s.signIn(d2, CODE);
    return { ...w, d2 };
  }

  it('remove_device removes another device of the same account only', () => {
    const { s, owner, d2 } = twoDevices();
    const stranger = s.user('stranger');
    const hexOwner = s.idOf(owner).toHexString();
    expect(() => s.call(stranger, mod.remove_device as any, { identity_hex: s.idOf(d2).toHexString() })).toThrow(/not_signed_in/);
    const o3 = s.user('o3');
    s.verify(o3);
    makeAccount(s, o3, CODE2);
    expect(() => s.call(o3, mod.remove_device as any, { identity_hex: hexOwner })).toThrow(/device not found/);
    expect(() => s.call(owner, mod.remove_device as any, { identity_hex: 'zz' })).toThrow(/invalid identity hex/);
    s.call(owner, mod.remove_device as any, { identity_hex: s.idOf(d2).toHexString() });
    expect(s.view(owner, mod.my_devices as any)).toHaveLength(1);
    expect(s.view(d2, mod.my_account as any)).toHaveLength(0);
    expect(s.view(d2, mod.my_property_reports as any)).toHaveLength(0);
  });

  it('set_device_label validates and renames', () => {
    const { s, owner } = twoDevices();
    expect(s.view(owner, mod.my_devices as any)[0].label).toMatch(/^Device /);
    s.call(owner, mod.set_device_label as any, { label: ' Roselyn iPhone ' });
    expect(s.view(owner, mod.my_devices as any).find((d: any) => d.is_current).label).toBe('Roselyn iPhone');
    expect(() => s.call(owner, mod.set_device_label as any, { label: '' })).toThrow(/1-40/);
    expect(() => s.call(s.user('x'), mod.set_device_label as any, { label: 'a' })).toThrow(/not_signed_in/);
  });

  it('delete_account hard-deletes the account, devices and bindings but keeps verifications, report data and the failure ledger', () => {
    const { s, owner, d2, propertyId, counts } = twoDevices();
    s.stepUp(d2, BAD); // a ledger row for a device of the account
    expect(s.h.db.code_attempt.count()).toBe(1n);
    s.call(owner, mod.delete_account as any, {});
    expect(s.h.db.account.count()).toBe(0n);
    expect(s.h.db.account_device.count()).toBe(0n);
    expect(s.h.db.account_property.count()).toBe(0n);
    // CHANGED (finding 2): the ledger is kept so delete + create cannot reset a lockout; it ages out on its own
    expect(s.h.db.code_attempt.count()).toBe(1n);
    expect(s.h.db.device_revocation.count()).toBe(0n); // delete_account does NOT revoke
    expect(s.view(d2, mod.my_account as any)).toHaveLength(0);
    expect([...s.h.db.verification.iter()].filter(v => v.state === 'verified')).toHaveLength(1);
    expect(counts(owner).my_property_reports).toBe(1);
    expect(counts(d2).my_property_reports).toBe(0);
    expect(s.view(owner, mod.my_verifications as any).some((v: any) => v.property_id === propertyId)).toBe(true);
    expect(() => s.call(owner, mod.delete_account as any, {})).toThrow(/not_signed_in/);
    // the old code no longer signs in anywhere; the owner can create a fresh account (even with the same code)
    expect(s.signIn(s.user('d3'), CODE)).toMatchObject({ ok: false, error: 'invalid_code' });
    expect(s.createAccount(owner, CODE).ok).toBe(true);
  });

  it('remove_device, delete_account and set_device_label ALWAYS need an active step-up window, even with require_stepup off (finding 5)', () => {
    const { s, owner, d2 } = twoDevices();
    expect(s.view(owner, mod.my_stepup as any)[0].require_stepup).toBe(false);
    const hexD2 = s.idOf(d2).toHexString();
    const expire = () => {
      s.advanceMs(16 * MIN); // window over (and the tick has not even run)
    };
    const all = () => {
      expect(() => s.call(owner, mod.remove_device as any, { identity_hex: hexD2 })).toThrow(/stepup_required/);
      expect(() => s.call(owner, mod.delete_account as any, {})).toThrow(/stepup_required/);
      expect(() => s.call(owner, mod.set_device_label as any, { label: 'Nope' })).toThrow(/stepup_required/);
    };
    expire();
    all();
    s.tick(); // after the tick cleared stepup_until: same answer
    all();
    expect(s.h.db.account.count()).toBe(1n);
    expect(s.view(owner, mod.my_devices as any)).toHaveLength(2);
    expect(s.h.db.device_revocation.count()).toBe(0n);
    // sign out stays free (no step-up) so a user can always leave
    s.call(d2, mod.sign_out_device as any, {});
    // a step-up restores everything
    expect(s.stepUp(owner, CODE).ok).toBe(true);
    s.call(owner, mod.set_device_label as any, { label: 'Fresh' });
    s.call(owner, mod.delete_account as any, {});
    expect(s.h.db.account.count()).toBe(0n);
    // a freshly signed-in device has the 15 minute window, so normal use works without a step-up call
    makeAccount(s, owner);
    s.call(owner, mod.set_device_label as any, { label: 'Again' });
    s.advanceMs(14 * MIN);
    s.call(owner, mod.set_device_label as any, { label: 'Still ok' });
  });

  it('require_stepup on: delete_account still needs the window (existing behavior)', () => {
    const { s, owner } = twoDevices();
    s.configureAccounts({ require_stepup: true });
    s.advanceMs(16 * MIN);
    expect(() => s.call(owner, mod.delete_account as any, {})).toThrow(/stepup_required/);
    expect(s.stepUp(owner, CODE).ok).toBe(true);
    s.call(owner, mod.delete_account as any, {});
    expect(s.h.db.account.count()).toBe(0n);
  });
});

describe('revocation: remove_device and sign_out_device cut off the device itself (finding 4)', () => {
  it('sign_out_device: the verifying device sees nothing until it signs in again; a device that never had an account is unaffected', () => {
    const { s, owner, read, counts, propertyId, rid } = ownerWorld();
    // never had an account: normal access, no revocation row anywhere
    expect(counts(owner).my_property_reports).toBe(1);
    expect(s.h.db.device_revocation.count()).toBe(0n);
    makeAccount(s, owner);
    expect(read(owner).ok).toBe(true);
    s.advanceMs(MIN);
    s.call(owner, mod.sign_out_device as any, {});
    expect(s.h.db.device_revocation.count()).toBe(1n);
    for (const n of Object.keys(counts(owner))) expect(counts(owner)[n], n).toBe(0);
    expect(read(owner).error).toBe('forbidden');
    expect(s.view(owner, mod.my_property_privates as any)).toHaveLength(0);
    expect(s.view(owner, mod.my_verifications as any).filter((v: any) => v.state === 'verified')).toHaveLength(0);
    expect(() => s.call(owner, mod.save_affected_intake as any, { property_id: propertyId, intake_json: '{}' })).toThrow(/unauthorized/);
    // another device of the (still existing) account keeps full access through the bound property
    const d2 = s.user('d2');
    expect(s.signIn(d2, CODE).ok).toBe(true);
    expect(counts(d2).my_property_reports).toBe(1);
    expect(read(d2).ok).toBe(true);
    // the revoked device signs in with a valid code: revocation lifted, it sees everything again
    expect(s.signIn(owner, CODE).ok).toBe(true);
    expect(s.h.db.device_revocation.count()).toBe(0n);
    expect(counts(owner).my_property_reports).toBe(1);
    expect(read(owner).ok).toBe(true);
    expect(rid).toBeDefined();
  });

  it('remove_device: the removed device (including the one that holds the verification row) loses access; the others keep it', () => {
    const { s, owner, read, counts } = ownerWorld();
    makeAccount(s, owner);
    const d2 = s.user('d2');
    s.signIn(d2, CODE);
    s.advanceMs(MIN);
    // d2 removes the ORIGINAL, verifying device
    s.call(d2, mod.remove_device as any, { identity_hex: s.idOf(owner).toHexString() });
    for (const n of Object.keys(counts(owner))) expect(counts(owner)[n], n).toBe(0);
    expect(read(owner).error).toBe('forbidden');
    expect(s.view(owner, mod.my_devices as any)).toHaveLength(0);
    expect(counts(d2).my_property_reports).toBe(1); // the bound property stays with the account
    expect(read(d2).ok).toBe(true);
    // removing yourself works too and revokes you
    s.call(d2, mod.remove_device as any, { identity_hex: s.idOf(d2).toHexString() });
    expect(counts(d2).my_property_reports).toBe(0);
    expect(s.h.db.device_revocation.count()).toBe(2n);
  });

  it('a removed device regains access only by a valid sign-in or by a NEW verification started after the revocation', () => {
    const { s, owner, counts } = ownerWorld();
    makeAccount(s, owner);
    s.advanceMs(MIN);
    s.call(owner, mod.sign_out_device as any, {});
    expect(counts(owner).my_property_reports).toBe(0);
    // a wrong code does not lift it
    expect(s.signIn(owner, BAD).ok).toBe(false);
    expect(counts(owner).my_property_reports).toBe(0);
    // a new verification (started after revoked_at) works for that new property only
    s.advanceMs(MIN);
    const v2 = s.verify(owner, FAR);
    expect(v2.state).toBe('verified');
    const owned = s.view(owner, mod.my_property_privates as any).map((p: any) => p.property_id);
    expect(owned).toEqual([v2.property_id]);
    expect(counts(owner).my_property_reports).toBe(0); // the OLD property's report is still not visible
    // the old verification stays unusable even though a newer one exists
    expect(s.view(owner, mod.my_verifications as any).filter((v: any) => v.state === 'verified').map((v: any) => v.id)).toEqual([v2.id]);
  });

  it('revocation also hides affected-person rows keyed by the revoked identity', () => {
    const { s, owner, counts } = ownerWorld();
    expect(counts(owner).my_affected_profiles).toBe(1);
    makeAccount(s, owner);
    s.advanceMs(MIN);
    s.call(owner, mod.sign_out_device as any, {});
    expect(counts(owner).my_affected_profiles).toBe(0);
    expect(counts(owner).my_recovery_plans).toBe(0);
    s.signIn(owner, CODE);
    expect(counts(owner).my_affected_profiles).toBe(1);
  });
});

describe('sign-in is inherit-only; a planted code cannot pull a victim\'s property into the attacker\'s account (finding 3)', () => {
  function planted() {
    const w = ownerWorld(); // `owner` owns the property of report `rid`: THIS is the victim
    const { s } = w;
    const victim = w.owner;
    // the attacker has their own verified property and account, and hands the victim a code
    const attacker = s.user('attacker');
    const mine = s.verify(attacker, FAR);
    makeAccount(s, attacker, CODE2);
    const attackerDevice2 = s.user('attacker-laptop');
    expect(s.signIn(attackerDevice2, CODE2).ok).toBe(true);
    return { ...w, victim, attacker, attackerDevice2, attackerProperty: mine.property_id };
  }

  it('the victim device signs in with the attacker\'s code: nothing of the victim moves into the attacker\'s account', () => {
    const { s, victim, attacker, attackerDevice2, attackerProperty, propertyId, read, counts } = planted();
    expect(s.signIn(victim, CODE2).ok).toBe(true);
    // no binding of the victim's property
    expect([...s.h.db.account_property.iter()].map(b => b.property_id)).toEqual([attackerProperty]);
    // the attacker's devices cannot read ANYTHING of the victim's property: views, blobs, affected-person rows, verification rows
    for (const who of [attacker, attackerDevice2]) {
      expect(counts(who).my_property_reports, 'reports').toBe(0);
      expect(counts(who).my_assessments).toBe(0);
      expect(counts(who).my_media_assets).toBe(0);
      expect(counts(who).my_affected_profiles).toBe(0); // the victim's intake is keyed by the victim's identity
      expect(counts(who).my_recovery_plans).toBe(0);
      expect(read(who).error).toBe('forbidden');
      expect(s.view(who, mod.my_property_privates as any).map((p: any) => p.property_id)).toEqual([attackerProperty]);
      const vs = s.view(who, mod.my_verifications as any);
      expect(vs.every((v: any) => v.property_id === attackerProperty)).toBe(true); // victim's verification row (name_on_doc etc.) not exposed
      expect(json(vs)).not.toContain(s.idOf(victim).toHexString());
      expect(() => s.call(who, mod.save_affected_intake as any, { property_id: propertyId, intake_json: '{}' })).toThrow(/unauthorized/);
    }
    // the victim keeps its own property (its own verification) ...
    expect(counts(victim).my_property_reports).toBe(1);
    expect(read(victim).ok).toBe(true);
    // ... and, by design, INHERITS the attacker account's properties (the documented inherit direction)
    expect(s.view(victim, mod.my_property_privates as any).map((p: any) => p.property_id).sort()).toEqual([propertyId, attackerProperty].sort());
    // the victim then signs out: the attacker's account still has nothing of the victim's
    s.advanceMs(MIN);
    s.call(victim, mod.sign_out_device as any, {});
    expect([...s.h.db.account_property.iter()].map(b => b.property_id)).toEqual([attackerProperty]);
    expect(counts(attacker).my_property_reports).toBe(0);
  });

  it('my_access_log `mine` covers only the viewer\'s own device or a device linked at the time of the read', () => {
    const { s, victim, attacker, attackerDevice2, rid, propertyId } = planted();
    const key = `media/${rid}/${HEX('3')}.jpg`;
    const rb = (who: any) => (mod.read_blob as any)(s.h.procedureContext(who), { object_key: key, seq: 0 });
    expect(rb(victim).ok).toBe(true); // read BEFORE the victim joins the attacker's account
    // the victim shares its property with the attacker through the proper path: the victim's own account is not involved
    s.advanceMs(2 * MIN);
    s.signIn(victim, CODE2);
    s.advanceMs(2 * MIN);
    expect(rb(victim).ok).toBe(true); // read after joining
    // the victim's reads are on the victim's property: the attacker sees none of them
    for (const who of [attacker, attackerDevice2]) {
      expect(s.view(who, mod.my_access_log as any).filter((r: any) => r.property_id === propertyId)).toHaveLength(0);
    }
    // the victim's own log: `mine` for its own device
    const log = s.view(victim, mod.my_access_log as any).filter((r: any) => r.kind === 'blob' && r.property_id === propertyId);
    expect(log.length).toBeGreaterThan(0);
    expect(log.every((r: any) => r.mine)).toBe(true);
  });

  it('a removed or signed-out device\'s earlier reads are not `mine`', () => {
    const { s, owner, rid, propertyId } = ownerWorld();
    makeAccount(s, owner);
    const d2 = s.user('d2');
    s.advanceMs(MIN);
    s.signIn(d2, CODE);
    s.advanceMs(MIN);
    const key = `media/${rid}/${HEX('3')}.jpg`;
    expect(((mod.read_blob as any)(s.h.procedureContext(d2), { object_key: key, seq: 0 })).ok).toBe(true);
    const blobMine = () => s.view(owner, mod.my_access_log as any).filter((r: any) => r.kind === 'blob' && r.property_id === propertyId).map((r: any) => r.mine);
    expect(blobMine()).toEqual([true]); // d2 is currently linked and read after linking
    s.call(owner, mod.remove_device as any, { identity_hex: s.idOf(d2).toHexString() });
    expect(blobMine()).toEqual([false]); // d2 is gone: its read is shown as someone else's
  });
});

describe('misc hardening', () => {
  it('a missing account_tick row self-heals on the next account call', () => {
    const { s, owner } = ownerWorld();
    for (const t of [...s.h.db.account_tick.iter()]) s.h.db.account_tick.scheduled_id.delete(t.scheduled_id);
    expect(s.h.db.account_tick.count()).toBe(0n);
    makeAccount(s, owner);
    expect(s.h.db.account_tick.count()).toBe(1n);
  });

  it('read_blob audit entries are deduped per (identity, object_key) within 60 s', () => {
    const { s, owner, rid, propertyId } = ownerWorld();
    const key = `media/${rid}/${HEX('3')}.jpg`;
    const rb = () => (mod.read_blob as any)(s.h.procedureContext(owner), { object_key: key, seq: 0 });
    const blobs = () => [...s.h.db.access_log.iter()].filter(l => l.kind === 'blob' && l.property_id === propertyId).length;
    for (let i = 0; i < 20; i++) expect(rb().ok).toBe(true);
    expect(blobs()).toBe(1);
    s.advanceMs(61_000);
    expect(rb().ok).toBe(true);
    expect(blobs()).toBe(2);
  });
});

describe('privacy', () => {
  it('no view ever returns a recovery code, its normalized form, a hash, the pepper or the config internals', () => {
    const { s, owner } = ownerWorld();
    s.configureAccounts({ require_stepup: false });
    makeAccount(s, owner);
    const d2 = s.user('d2');
    s.signIn(d2, CODE);
    s.signIn(s.user('prober'), BAD);
    s.replaceCode(owner, CODE, NEW_CODE);
    const other = s.user('other');
    const pepper = s.h.db.account_config.id.find(0)!.hash_pepper;
    const secrets = [
      CODE, normalizeRecoveryCode(CODE), NEW_CODE, normalizeRecoveryCode(NEW_CODE), normalizeRecoveryCode(BAD), pepper,
      ...[...s.h.db.account.iter()].map(a => a.recovery_hash),
      recoveryHash(pepper, normalizeRecoveryCode(CODE)), // not derivable from any view output
      sha256Hex(normalizeRecoveryCode(CODE)),
    ];
    const views = Object.keys(mod).filter(n => /^(my_|svc_|web_|admin_account)/.test(n));
    for (const who of [owner, d2, other, s.worker, s.internal]) {
      for (const name of views) {
        const out = json(s.view(who, (mod as any)[name]));
        for (const sec of secrets) expect(out, `${name} leaks ${sec.slice(0, 6)}`).not.toContain(sec);
      }
    }
    // the removed email-era surface is gone
    for (const gone of ['request_email_code', 'verify_email_code', 'admin_set_email_config', 'my_demo_code', 'my_email_challenge', 'my_auth_status', 'admin_email_config']) {
      expect((mod as any)[gone], gone).toBeUndefined();
    }
  });

  it('procedure results carry no secret and no account existence hint', () => {
    const { s, owner } = ownerWorld();
    makeAccount(s, owner);
    const a = s.signIn(s.user('a'), BAD);
    const b = s.signIn(s.user('b'), testCode('also-wrong'));
    expect(a).toEqual(b);
    expect(Object.keys(a).sort()).toEqual(['attempts_left', 'error', 'ok', 'retry_after_s']);
  });

  it('account_maintenance rejects clients and accepts the scheduler', () => {
    const s = setup();
    const arg = { arg: { scheduled_id: 1n, scheduled_at: { tag: 'Interval', value: 0n } } };
    expect(() => s.call(s.user('alice'), mod.account_maintenance as any, arg)).toThrow(/scheduled only/);
    expect(() => s.call(s.worker, mod.account_maintenance as any, arg)).toThrow(/scheduled only/);
    expect(() => s.call(s.internal, mod.account_maintenance as any, arg)).not.toThrow();
  });

  it('init and the first config call schedule the 60 s tick exactly once', () => {
    const s = setup();
    expect(s.h.db.account_tick.count()).toBe(1n);
    s.configureAccounts();
    s.configureAccounts();
    expect(s.h.db.account_tick.count()).toBe(1n);
  });
});
